code_example:
union Data {
    int i;
    float f;
    char s[10];
};

// Size is max(sizeof(int), sizeof(float), sizeof(char[10]))
// Likely 12 bytes on many systems (due to array size/padding)
Data d;
d.i = 42;          // Active member is i
// float f is now invalid
d.f = 3.14f;       // Active member is f
// int i is now invalid

// Accessing wrong member is UB (or implementation defined behavior)
// but often results in garbage data:
// printf("%d", d.i); // Danger!
